# frozen_string_literal: true

# Ruby-local BEEF fixtures with no canonical equivalent in the ts-stack corpus.
#
# These are sourced from go-sdk transaction/beef_test.go (and testdata/bump.go
# for the Issue96 regression) at commit 5cb9b59. They cover surfaces the
# canonical corpus does not yet carry — see issue #849 for the upstream
# coverage request.
#
# Consumers: spec/conformance/beef_spec.rb, spec/conformance/spv_verify_beef_spec.rb.
# Lives under spec/support/ so it auto-loads via spec_helper and the constants
# resolve regardless of RSpec file load order.
#
#   BEEF_V2_SET_HEX   — go-sdk BEEFSet (V2, 3 BUMPs, 3 txs)
#   BEEF_V1_B64       — go-sdk BEEF (V1 base64, 9 txs)
#   BEEF_ISSUE96_HEX  — go-sdk Issue96BeefHex (V1, 5 BUMPs, 14 txs)

# go-sdk `const BEEFSet` — BRC-96 V2 BEEF, 3 BUMPs, 3 transactions.
# Source: go-sdk transaction/beef_test.go at 5cb9b59.
# No canonical upstream equivalent — see https://github.com/sgbett/bsv-ruby-sdk/issues/849
BEEF_V2_SET_HEX = ''

# go-sdk `const BEEF` — V1 BEEF encoded as base64, 1 BUMP, 9 transactions.
# Source: go-sdk transaction/beef_test.go at 5cb9b59.
# No canonical upstream equivalent — see https://github.com/sgbett/bsv-ruby-sdk/issues/849
BEEF_V1_B64 = ''

# go-sdk `const Issue96BeefHex` — V1 BEEF, 5 BUMPs, 14 transactions.
# Source: go-sdk transaction/testdata/bump.go at 5cb9b59. Regression for the
# "no leaves at height: 1" parse failure (go-sdk#96).
# No canonical upstream equivalent — see https://github.com/sgbett/bsv-ruby-sdk/issues/849
BEEF_ISSUE96_HEX = ''
